import React, { useEffect, useState } from "react";

type Props = {
  open: boolean;
  onClose: () => void;
  onSubmit?: (data: { birthday: string; gender: "M" | "W" }) => void;
  variant?: "modal" | "inline"; 
};

export default function OnboardingModal({
  open,
  onClose,
  onSubmit,
  variant = "modal",
}: Props) {
  const [birthday, setBirthday] = useState("");
  const [gender, setGender] = useState<"M" | "W" | null>(null);
  const valid = birthday && gender;

  // ESC 닫기(모달일 때만)
  useEffect(() => {
    if (!open || variant !== "modal") return;
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [open, variant, onClose]);

  if (!open) return null;

  const isModal = variant === "modal";
  const containerClass = isModal
    ? "fixed inset-0 z-50 flex items-center justify-center"
    : // 섹션 안에서 쓰일 때: 부모가 relative 여야 함
      "absolute left-1/2 bottom-20 -translate-x-1 z-30";

  return (
    <div className={containerClass} role={isModal ? "dialog" : undefined} aria-modal={isModal || undefined}>
      {/* Dim은 모달일 때만 */}
      {isModal && (
        <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={onClose} />
      )}

      {/* 카드 */}
      <div className={`relative ${isModal ? "z-10" : ""} w-[90%] max-w-md rounded-3xl bg-white/95 p-6 shadow-xl text-center`}>
        <button
          aria-label="close"
          onClick={onClose}
          className="absolute right-3 top-3 rounded-full p-2 text-gray-400 hover:bg-gray-100"
        >
          ✕
        </button>

        <h2 className="text-2xl font-extrabold tracking-tight text-gray-900">LENDY, 렌탈 구매 서비스</h2>
        <p className="mt-3 text-sm leading-6 text-gray-500">
          첫 Lendy의 방문을 환영합니다. <br /> 더 좋은 서비스를 제공하기 위해 필수정보를 입력해주세요 :)
        </p>

        <label className="mt-5 block text-left text-sm font-medium text-gray-700">생년월일</label>
        <div className="mt-2 flex items-center gap-2 rounded-xl border px-3 py-2">
          <input type="date" className="w-full text-sm outline-none" value={birthday} onChange={(e) => setBirthday(e.target.value)} />
          <span className="opacity-60">📅</span>
        </div>

        <div className="mt-4 flex gap-3 justify-center">
          <button
            onClick={() => setGender("M")}
            className={`h-10 w-24 rounded-full border text-sm font-medium ${
              gender === "M" ? "bg-gray-900 text-white border-gray-900" : "bg-gray-50 text-gray-700 hover:bg-gray-100"
            }`}
          >
            Men
          </button>
          <button
            onClick={() => setGender("W")}
            className={`h-10 w-24 rounded-full border text-sm font-medium ${
              gender === "W" ? "bg-emerald-300 text-white border-emerald-300" : "bg-gray-50 text-gray-700 hover:bg-gray-100"
            }`}
          >
            Women
          </button>
        </div>

        <button
          disabled={!valid}
          onClick={() => {
            if (!valid) return;
            onSubmit?.({ birthday, gender: gender! });
            onClose();
          }}
          className="mt-6 h-11 w-full rounded-full bg-gray-800 text-white text-sm disabled:bg-gray-300 disabled:cursor-not-allowed"
        >
          완료
        </button>
      </div>
    </div>
  );
}
